/* @lc app=leetcode id=3161 lang=kotlin */
class Solution { fun getResults(queries: Array<IntArray>): List<Boolean> = (queries.maxOf { it[1] } + 1).let { N -> IntArray(4 * N + 5).let { tree -> DeepRecursiveFunction<IntArray, Unit> { args -> args[0].let { node -> args[1].let { l -> args[2].let { r -> args[3].let { idx -> args[4].let { v -> if (l == r) tree[node] = v else ((l + r) / 2).let { mid -> (if (idx <= mid) callRecursive(intArrayOf(2 * node, l, mid, idx, v)) else callRecursive(intArrayOf(2 * node + 1, mid + 1, r, idx, v))).also { tree[node] = maxOf(tree[2 * node], tree[2 * node + 1]) } } } } } } } }.let { update -> DeepRecursiveFunction<IntArray, Int> { args -> args[0].let { node -> args[1].let { l -> args[2].let { r -> args[3].let { ql -> args[4].let { qr -> if (ql > r || qr < l) 0 else if (ql <= l && r <= qr) tree[node] else maxOf(callRecursive(intArrayOf(2 * node, l, (l + r) / 2, ql, qr)), callRecursive(intArrayOf(2 * node + 1, (l + r) / 2 + 1, r, ql, qr))) } } } } } }.let { query -> java.util.TreeSet<Int>().apply { add(0) }.let { obs -> queries.mapNotNull { q -> if (q[0] == 1) q[1].let { x -> obs.lower(x)!!.let { prev -> obs.higher(x)?.let { next -> update.callRecursive(intArrayOf(1, 0, N, next, next - x)) }.run { update.callRecursive(intArrayOf(1, 0, N, x, x - prev)) }.run { obs.add(x) }.run { null } } } else q[1].let { x -> q[2].let { sz -> obs.floor(x)!!.let { p -> maxOf(query.callRecursive(intArrayOf(1, 0, N, 0, p)), x - p) >= sz } } } } } } } } } }